s32 BPF_STRUCT_OPS(simple_select_cpu, struct task_struct *p,
                   s32 prev_cpu, u64 wake_flags)
{
    bool is_idle = false;
    s32 cpu = scx_bpf_select_cpu_dfl(p, prev_cpu, wake_flags, &is_idle);
    if (is_idle)   /* idle CPU found: skip enqueue entirely */
        scx_bpf_dsq_insert(p, SCX_DSQ_LOCAL, SCX_SLICE_DFL, 0);
    return cpu;    /* a hint, not binding */
}

void BPF_STRUCT_OPS(simple_enqueue, struct task_struct *p, u64 enq_flags)
{
    u64 vtime = p->scx.dsq_vtime;
    if (time_before(vtime, vtime_now - SCX_SLICE_DFL))
        vtime = vtime_now - SCX_SLICE_DFL;   /* cap sleeper credit */
    scx_bpf_dsq_insert_vtime(p, SHARED_DSQ, SCX_SLICE_DFL, vtime, enq_flags);
}

void BPF_STRUCT_OPS(simple_dispatch, s32 cpu, struct task_struct *prev)
{
    scx_bpf_dsq_move_to_local(SHARED_DSQ, 0);
}

void BPF_STRUCT_OPS(simple_running, struct task_struct *p)
{
    if (time_before(vtime_now, p->scx.dsq_vtime))
        vtime_now = p->scx.dsq_vtime;
}

void BPF_STRUCT_OPS(simple_stopping, struct task_struct *p, bool runnable)
{
    u64 delta = scale_by_task_weight_inverse(p, SCX_SLICE_DFL - p->scx.slice);
    scx_bpf_task_set_dsq_vtime(p, p->scx.dsq_vtime + delta);
}

void BPF_STRUCT_OPS(simple_dispatch, s32 cpu, struct task_struct *prev)
{
    if (prev && (prev->scx.flags & SCX_TASK_QUEUED)) {   /* still runnable */
        struct task_struct *head = __COMPAT_scx_bpf_dsq_peek(SHARED_DSQ);
        u64 used = SCX_SLICE_DFL - prev->scx.slice;
        u64 v = prev->scx.dsq_vtime + scale_by_task_weight_inverse(prev, used);

        if (!head || time_before(v, head->scx.dsq_vtime)) {
            scx_bpf_task_set_dsq_vtime(prev, v);   /* charge it here...     */
            scx_bpf_task_set_slice(prev, SCX_SLICE_DFL);
            return;                                /* ...the core keeps prev */
        }
    }
    scx_bpf_dsq_move_to_local(SHARED_DSQ, 0);
}

#include <scx/common.bpf.h>
char _license[] SEC("license") = "GPL";
const volatile bool fifo_sched;          /* set by the loader before load */
UEI_DEFINE(uei);                         /* exit info shared with user space */
#define SHARED_DSQ 0

struct {                                 /* [local, global] counters per CPU */
    __uint(type, BPF_MAP_TYPE_PERCPU_ARRAY);
    __uint(key_size, sizeof(u32));
    __uint(value_size, sizeof(u64));
    __uint(max_entries, 2);
} stats SEC(".maps");

static void stat_inc(u32 idx)
{
    u64 *cnt_p = bpf_map_lookup_elem(&stats, &idx);
    if (cnt_p)
        (*cnt_p)++;                      /* this CPU's own copy */
}

/* select_cpu, enqueue, dispatch, running, stopping: as in lesson 4;
   simple_enable() starts each new task at vtime_now */

s32 BPF_STRUCT_OPS_SLEEPABLE(simple_init)
{
    return scx_bpf_create_dsq(SHARED_DSQ, -1);   /* -1: any NUMA node */
}

void BPF_STRUCT_OPS(simple_exit, struct scx_exit_info *ei)
{
    UEI_RECORD(uei, ei);                 /* copy kind, reason, message */
}

SCX_OPS_DEFINE(simple_ops,               /* SEC(".struct_ops.link") */
               .select_cpu = (void *)simple_select_cpu,
               .enqueue    = (void *)simple_enqueue,
               .dispatch   = (void *)simple_dispatch,
               .init       = (void *)simple_init,
               .exit       = (void *)simple_exit,
               .name       = "simple");

int main(int argc, char **argv)
{
    struct scx_simple *skel;
    struct bpf_link *link;
    __u64 ecode;

    signal(SIGINT, sigint_handler);              /* Ctrl-C sets exit_req */
restart:
    skel = SCX_OPS_OPEN(simple_ops, scx_simple); /* open the skeleton    */
    /* option -f: skel->rodata->fifo_sched = true; (before load)        */
    SCX_OPS_LOAD(skel, simple_ops, scx_simple, uei);   /* verify, load   */
    link = SCX_OPS_ATTACH(skel, simple_ops, scx_simple); /* now active   */

    while (!exit_req && !UEI_EXITED(skel, uei)) {
        __u64 stats[2];
        read_stats(skel, stats);       /* sum the per-CPU counters      */
        printf("local=%llu global=%llu\n", stats[0], stats[1]);
        sleep(1);
    }

    bpf_link__destroy(link);           /* unregister: tasks go to fair  */
    ecode = UEI_REPORT(skel, uei);     /* prints "EXIT: <reason> (...)" */
    scx_simple__destroy(skel);
    if (!exit_req && UEI_ECODE_RESTART(ecode))
        goto restart;
    return 0;
}

struct task_ctx { u64 nr_runs; };
struct {
    __uint(type, BPF_MAP_TYPE_TASK_STORAGE);
    __uint(map_flags, BPF_F_NO_PREALLOC);
    __type(key, int);
    __type(value, struct task_ctx);
} task_ctx_stor SEC(".maps");

s32 BPF_STRUCT_OPS(simple_init_task, struct task_struct *p,
                   struct scx_init_task_args *args)
{
    if (bpf_task_storage_get(&task_ctx_stor, p, 0,
                             BPF_LOCAL_STORAGE_GET_F_CREATE))
        return 0;
    return -ENOMEM;                      /* refuse the task: no memory */
}

void BPF_STRUCT_OPS(simple_running, struct task_struct *p)
{
    struct task_ctx *tctx = bpf_task_storage_get(&task_ctx_stor, p, 0, 0);
    if (tctx)
        tctx->nr_runs++;
    /* ... the existing vtime_now update ... */
}

void BPF_STRUCT_OPS(simple_exit_task, struct task_struct *p,
                    struct scx_exit_task_args *args)
{
    struct task_ctx *tctx = bpf_task_storage_get(&task_ctx_stor, p, 0, 0);
    if (tctx && tctx->nr_runs > 1000)
        bpf_printk("%s[%d] ran %llu times", p->comm, p->pid, tctx->nr_runs);
}

void BPF_STRUCT_OPS(my_enqueue, struct task_struct *p, u64 enq_flags)
{
    if (is_urgent(p)) {                      /* your policy decides */
        s32 cpu = scx_bpf_task_cpu(p);       /* CPU it last ran on  */
        /* head of that CPU's local DSQ; its current task's slice is
           zeroed and the CPU is kicked into the scheduling path */
        scx_bpf_dsq_insert(p, SCX_DSQ_LOCAL_ON | cpu, SCX_SLICE_DFL,
                           enq_flags | SCX_ENQ_PREEMPT);
        return;
    }
    scx_bpf_dsq_insert(p, SHARED_DSQ, SCX_SLICE_DFL, enq_flags);

    s32 idle = scx_bpf_pick_idle_cpu(p->cpus_ptr, 0);  /* claims it */
    if (idle >= 0)
        scx_bpf_kick_cpu(idle, SCX_KICK_IDLE);  /* wake it to dispatch */
}

ops.init_task();          /* A new task is created */
ops.enable();             /* Enable BPF scheduling for the task */
while (task in SCHED_EXT) {
    if (task can migrate)
        ops.select_cpu(); /* Called on wakeup (optimization) */
    ops.runnable();       /* Task becomes ready to run */
    while (task_is_runnable(task)) {
        if (task is not in a DSQ || task->scx.slice == 0) {
            ops.enqueue();    /* Task can be added to a DSQ */
            /* Task property change (i.e., affinity, nice, etc.)? */
            if (sched_change(task)) {
                ops.dequeue();   /* Exiting BPF scheduler custody */
                ops.quiescent();
                /* Property change callback, e.g. ops.set_weight() */
                ops.runnable();
                continue;
            }
            /* Any usable CPU becomes available */
            ops.dispatch();   /* Task is moved to a local DSQ */
            ops.dequeue();    /* Exiting BPF scheduler custody */
        }
        ops.running();        /* Task starts running on its assigned CPU */
        while (task_is_runnable(task) && task->scx.slice > 0) {
            ops.tick();       /* Called every 1/HZ seconds */
            if (task->scx.slice == 0)
                ops.dispatch(); /* task->scx.slice can be refilled */
        }
        ops.stopping();       /* Task stops running (time slice expires or wait) */
    }
    ops.quiescent();          /* Task releases its assigned CPU (wait) */
}
ops.disable();            /* Disable BPF scheduling for the task */
ops.exit_task();          /* Task is destroyed */
